package com.smartproperty.platform.meter.service.impl;
import com.smartproperty.platform.meter.*;import com.smartproperty.platform.meter.mapper.MeterSimulationMapper;import com.smartproperty.platform.meter.mapper.MeterSimulationMapper.*;import com.smartproperty.platform.meter.service.MeterSimulationService;import com.smartproperty.platform.meter.vo.MeterSimulationResultVO;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;
@Service public class MeterSimulationServiceImpl implements MeterSimulationService {private final MeterSimulationMapper mapper;private final MeterSimulatorProperties p;private final Map<String,Long> last=new HashMap<>();public MeterSimulationServiceImpl(MeterSimulationMapper m,MeterSimulatorProperties x){mapper=m;p=x;}
 @Transactional public MeterSimulationResultVO simulateNow(){return simulate(List.of("ELECTRICITY","WATER","GAS"),LocalDateTime.now().truncatedTo(ChronoUnit.MINUTES));}
 public synchronized void scheduledTick(){if(!p.isEnabled())return;long now=System.currentTimeMillis();if("DEMO".equalsIgnoreCase(p.getMode())){due("ELECTRICITY",p.getElectricityDemoIntervalMs(),now);due("WATER",p.getWaterDemoIntervalMs(),now);due("GAS",p.getGasDemoIntervalMs(),now);}else{LocalDateTime t=LocalDateTime.now();if(t.getMinute()%15==0)due("ELECTRICITY",900000,now);if(t.getMinute()==0)due("WATER",3600000,now);if(t.getHour()==2&&t.getMinute()==0)due("GAS",86400000,now);}}
 private void due(String fee,long interval,long now){if(now-last.getOrDefault(fee,0L)>=interval){last.put(fee,now);simulate(List.of(fee),LocalDateTime.now().truncatedTo(ChronoUnit.MINUTES));}}
 @Transactional MeterSimulationResultVO simulate(List<String> types,LocalDateTime at){var states=mapper.selectActiveMeterStates(types);if(states.isEmpty())return new MeterSimulationResultVO(0,0,0,0,at.toString());var ids=states.stream().map(MeterState::meterId).toList();var existing=new HashSet<>(mapper.selectExistingMeterIds(ids,at));var readings=new ArrayList<ReadingCommand>();for(var s:states)if(!existing.contains(s.meterId())){BigDecimal base=s.latestReading()==null?s.initialReading():s.latestReading();readings.add(new ReadingCommand(s.meterId(),at,base.add(increment(s,at)).setScale(3,RoundingMode.HALF_UP),"Stage H deterministic simulator"));}int inserted=readings.isEmpty()?0:mapper.insertReadings(readings);return new MeterSimulationResultVO(states.size(),inserted,existing.size(),Math.max(0,readings.size()-inserted),at.toString());}
 private BigDecimal increment(MeterState s,LocalDateTime t){int hour=t.getHour();int wave=(int)((s.meterId()*31+t.getDayOfYear()*17+t.getMinute())%7);double base="ELECTRICITY".equals(s.feeCode())?(hour>=18||hour<=8?.18:.09):"WATER".equals(s.feeCode())?(hour>=6&&hour<=9||hour>=18&&hour<=22?.045:.018):((hour==7||hour==12||hour==18)?.028:.006);return BigDecimal.valueOf(base+wave*.003);}}
